#!/bin/zsh
# Step 8: X-video relaxed idle clip from master C (S still) via the Grok subscription CLI (headless). Amplitude dial aimed inside the 1.96–4.90 %H band.
set -e
B=/Users/admin/Games/reincarnated-collaboration/astra_test_01/burst
STILL="$B/runs/C-1/artifacts/K1p-gen-01/k1p_master_C.png"
OUTDIR="$B/runs/C-1/xvideo/in"; mkdir -p "$OUTDIR"; WORK="$HOME/astra-burst/grok/idle_C"; mkdir -p "$WORK"
PROMPT='The character stands still and breathes, facing the camera, on a flat solid pure green (#00ff00) background that stays completely unchanged and empty (no scenery, no shadows, no particles). Camera locked, no zoom, no pan; the figure stays centred at the same size. A slow, calm, CLEARLY VISIBLE relaxed breath, drawn about a third bigger than life the way hand-drawn game animation does it: the chest and shoulders rise and broaden on the inhale and settle on the exhale, once every two seconds; the collar and the tabard chest plane visibly widen at the peak; the head rides gently with the breath and does not turn; the eyes stay still; the staff stays planted in her hand; both feet stay planted and never slide; the belt, satchel and legs do not move. Same face, same hair, same costume, same colours in every frame. Hand-drawn 2D animation, one continuous shot, no cuts. Loop: the last frame matches the first.'
cd "$WORK"
~/.grok/bin/grok -p "Use your image_to_video tool ONCE with these exact arguments: image = $STILL (this still is the FIRST frame), prompt = \"$PROMPT\", duration = 6, resolution = 720p. When it returns, save/copy the resulting MP4 into the current directory as idle_C_grok.mp4 (download it if the tool returns a URL), then print exactly one line: SAVED <absolute path> <size in bytes> <costUSD if reported>. Do nothing else; do not edit the image; do not generate a second video." --always-approve 2>&1 | tail -15
ls -la "$WORK"; f=$(ls "$WORK"/*.mp4 2>/dev/null | head -1); [ -n "$f" ] && cp "$f" "$OUTDIR/idle_C_grok.mp4" && echo "COPIED → $OUTDIR/idle_C_grok.mp4 ($(stat -f %z "$OUTDIR/idle_C_grok.mp4") bytes)" && /opt/homebrew/bin/ffprobe -v error -select_streams v:0 -show_entries stream=width,height,r_frame_rate,nb_frames,duration -of default=nw=1 "$OUTDIR/idle_C_grok.mp4"
